import{_ as o,C as l,o as d,c as s,a5 as t,E as r}from"./chunks/framework.CX7j2CRp.js";const T=JSON.parse('{"title":"加密记录","description":"在浏览器本地维护支持多个长期独立密钥的加密记录。","frontmatter":{"title":"加密记录","description":"在浏览器本地维护支持多个长期独立密钥的加密记录。"},"headers":[],"relativePath":"pages/vault.md","filePath":"pages/vault.md","lastUpdated":1790738697000}'),c={name:"pages/vault.md"};function i(_,e,n,p,u,m){const a=l("EstateVault");return d(),s("div",null,[e[0]||(e[0]=t('<h1 id="加密记录" tabindex="-1">加密记录 <a class="header-anchor" href="#加密记录" aria-label="Permalink to &quot;加密记录&quot;">​</a></h1><p>这是一份可公开分发的加密记录。外层使用 Base64 文本封装，仓库中只保存一个普通的 <code>data.dat</code> 数据文件。首次创建时生成一把随机 DEK，并由多个家人密钥分别包裹；以后每次更新正文都复用原 DEK 和原全部密钥槽，只重新生成正文的 AES-GCM IV 与密文。</p><p>因此，只要没有主动做密钥轮换，<strong>第一次发给家人的恢复密钥可以长期保持有效</strong>。</p><blockquote><p>所有加解密都在浏览器本地完成。将生成的 Base64 数据保存到 <code>public/assets/data.dat</code> 并提交；GitHub Actions 只负责构建和发布密文，不需要任何解密密钥。</p></blockquote>',4)),r(a),e[1]||(e[1]=t('<h2 id="离线恢复" tabindex="-1">离线恢复 <a class="header-anchor" href="#离线恢复" aria-label="Permalink to &quot;离线恢复&quot;">​</a></h2><p>即使博客、域名或 GitHub Pages 失效，也可以使用 <code>recovery.html</code> 离线解密。长期建议同时保存：</p><ul><li><code>recovery.html</code></li><li><code>RECOVERY.txt</code></li><li>最新的 <code>data.dat</code></li><li>至少一个有效恢复密钥</li></ul><p><code>recovery.html</code> 是单文件、本地运行的解码器，不依赖 CDN 或网络请求。</p>',4))])}const E=o(c,[["render",i]]);export{T as __pageData,E as default};
